@app.cell
def _(mo):
    methodology_accordion = mo.accordion(
        {
            "📐 1. Level-Anchor Backcasting Trajectory Formulation": mo.md(
                r"""
                For jurisdiction $c$ and retrospective year $t \in \{2015, \dots, 2020\}$:
                $$\hat{F}_{c,t} = A_{c,2020} \cdot \exp\Big(b_c^* \cdot (t - 2020)\Big)$$
                - **$A_{c,2020}$**: Official v6 floorspace level anchor. At $t=2020$, $\exp(0) = 1$, ensuring **exact mathematical consistency** with established benchmarks.
                - **$b_c^*$**: Shrunk annual growth rate back-projected from 2020.
                """
            ),
            "🛰️ 2. Empirical Bayes Quality-Adaptive Shrinkage": mo.md(
                r"""
                Satellite coverage differs in pixel noise and cloud interference. We quantify observational fidelity via $Q_c \in [0, 1]$:
                $$\sigma^2_{c,\text{slope}} \leftarrow \sigma^2_{c,\text{slope}} \cdot \Big[1 + 2.0 \cdot (1 - Q_c)\Big]$$
                $$\lambda_c = \frac{\sigma^2_{c,\text{slope}}}{\sigma^2_{c,\text{slope}} + \tau^2}, \quad b_c^* = (1 - \lambda_c) b_c + \lambda_c b_{\text{global}}$$
                - Countries with high-fidelity observational series retain localized empirical slopes ($\lambda_c \to 0$).
                - Noisy series shrink toward the global macro growth rate $b_{\text{global}} \approx 2.07\%/\text{yr}$.
                """
            ),
            "⚖️ 3. Multi-Source Dual Uncertainty Propagation": mo.md(
                r"""
                Predictive log standard deviation $\sigma_{c,t}$ compounds retrospective distance, flow residual variance, and spatial morphology:
                $$\sigma_{c,t}^2 = \sigma_{\text{anchor}}^2 + (2020 - t)^2 \cdot \sigma_{c,\text{slope}}^2 + \sigma_{\text{BSO}}^2 + \sigma_{\text{OBAT}}^2$$
                Quantiles follow log-normal distributions:
                $$P_{10} = \hat{F}_{c,t} e^{-1.28155 \sigma_{c,t}}, \quad P_{50} = \hat{F}_{c,t}, \quad P_{90} = \hat{F}_{c,t} e^{+1.28155 \sigma_{c,t}}$$
                """
            ),
        }
    )

    mo.vstack([
        mo.md("### 🔬 Mathematical Framework & Rigor"),
        methodology_accordion,
    ])
    return


