@app.cell
def _(alt, df_envelope, df_final, mo, pd):
    global_ts = (
        df_final.groupby("year")
        .agg(
            p10=("floorspace_p10_m2", lambda x: x.sum() / 1e9),
            p50=("floorspace_p50_m2", lambda x: x.sum() / 1e9),
            p90=("floorspace_p90_m2", lambda x: x.sum() / 1e9),
        )
        .reset_index()
    )

    env_ts = (
        df_envelope.groupby("year")
        .agg(
            min_scenario=("min_m2", lambda x: x.sum() / 1e9),
            max_scenario=("max_m2", lambda x: x.sum() / 1e9),
            baseline=("baseline", lambda x: x.sum() / 1e9),
            ghs_gsr=("ghs_gsr", lambda x: x.sum() / 1e9),
            recc_lemd=("recc_LEMD_Base", lambda x: x.sum() / 1e9),
            recc_ssp1=("recc_SSP1_Base", lambda x: x.sum() / 1e9),
            recc_ssp2=("recc_SSP2_Base", lambda x: x.sum() / 1e9),
        )
        .reset_index()
    )

    merged_ts = pd.merge(global_ts, env_ts, on="year")

    scen_band = (
        alt.Chart(merged_ts)
        .mark_area(opacity=0.18, color="#10b981")
        .encode(
            x=alt.X("year:O", title="Year"),
            y=alt.Y("min_scenario:Q", title="Total GFA (Billion m²)", scale=alt.Scale(domain=[150, 700])),
            y2="max_scenario:Q",
        )
    )

    ci_band = (
        alt.Chart(merged_ts)
        .mark_area(opacity=0.25, color="#3b82f6")
        .encode(
            x="year:O",
            y="p10:Q",
            y2="p90:Q",
        )
    )

    line = (
        alt.Chart(merged_ts)
        .mark_line(point=alt.OverlayMarkDef(filled=True, size=80, color="#1d4ed8"), color="#1d4ed8", strokeWidth=3.5)
        .encode(
            x="year:O",
            y="p50:Q",
            tooltip=[
                alt.Tooltip("year:O", title="Year"),
                alt.Tooltip("p50:Q", format=".2f", title="P50 Estimate (bn m²)"),
                alt.Tooltip("p10:Q", format=".2f", title="P10 Lower Bound (bn m²)"),
                alt.Tooltip("p90:Q", format=".2f", title="P90 Upper Bound (bn m²)"),
                alt.Tooltip("min_scenario:Q", format=".2f", title="Min Scenario (bn m²)"),
                alt.Tooltip("max_scenario:Q", format=".2f", title="Max Scenario (bn m²)"),
            ],
        )
    )

    chart = (
        (scen_band + ci_band + line)
        .properties(
            width=850,
            height=380,
        )
        .configure_axis(
            labelFontSize=12,
            titleFontSize=13,
            gridColor="#f1f5f9",
        )
        .configure_view(strokeWidth=0)
    )

    mo.vstack([
        mo.md("### 🌐 Global Stock Trajectory & Uncertainty Envelope (2015–2020)"),
        mo.md(
            """
            * **Navy Line with Dots**: Primary $P_{50}$ point estimate.
            * **Soft Blue Band**: 80% empirical predictive interval ($P_{10} \sim P_{90}$).
            * **Green Shaded Area**: Multi-scenario sensitivity envelope (RECC LEMD/SSP1/SSP2 & GSR).
            """
        ),
        mo.ui.altair_chart(chart),
    ])
    return


