@app.cell
def _(alt, country_dropdown, df_envelope, df_final, mo, pd):
    selected_country = country_dropdown.value

    c_final = df_final[df_final["country_id"] == selected_country].sort_values("year")
    c_env = df_envelope[df_envelope["country_id"] == selected_country].sort_values("year")
    c_merged = pd.merge(c_final, c_env, on=["country_id", "year"])

    c_chart_line = (
        alt.Chart(c_merged)
        .mark_line(point=alt.OverlayMarkDef(filled=True, size=70, color="#d97706"), color="#d97706", strokeWidth=3)
        .encode(
            x=alt.X("year:O", title="Year"),
            y=alt.Y("floorspace_m2:Q", title="Gross Floor Area (m²)", scale=alt.Scale(zero=False)),
            tooltip=[
                alt.Tooltip("year:O", title="Year"),
                alt.Tooltip("floorspace_m2:Q", format=",.0f", title="P50 Estimate (m²)"),
                alt.Tooltip("floorspace_p10_m2:Q", format=",.0f", title="P10 Lower (m²)"),
                alt.Tooltip("floorspace_p90_m2:Q", format=",.0f", title="P90 Upper (m²)"),
                alt.Tooltip("ghs_long_slope_per_year:Q", format=".4f", title="Annual Slope"),
            ],
        )
    )

    c_chart_band = (
        alt.Chart(c_merged)
        .mark_area(opacity=0.25, color="#f59e0b")
        .encode(
            x="year:O",
            y="floorspace_p10_m2:Q",
            y2="floorspace_p90_m2:Q",
        )
    )

    c_chart = (
        (c_chart_band + c_chart_line)
        .properties(
            width=850,
            height=300,
        )
        .configure_axis(gridColor="#f8fafc")
        .configure_view(strokeWidth=0)
    )

    _c_2015 = c_final[c_final["year"] == 2015]["floorspace_m2"].iloc[0]
    _c_2020 = c_final[c_final["year"] == 2020]["floorspace_m2"].iloc[0]
    _growth = (_c_2020 / _c_2015 - 1) * 100
    _slope = c_final["ghs_long_slope_per_year"].iloc[0]
    _qual = c_final["ghs_quality_score"].iloc[0]
    _sd = c_final[c_final["year"] == 2020]["log_sd"].iloc[0]

    country_metrics = mo.hstack(
        [
            mo.stat(value=f"{_c_2020:,.0f} m²", label="2020 Anchor", caption="Fixed level reference"),
            mo.stat(value=f"{_c_2015:,.0f} m²", label="2015 Retrospective", caption="Model backcasted start"),
            mo.stat(value=f"+{_growth:.2f}%", label="5-Year Growth", caption="Compounded change"),
            mo.stat(value=f"{_slope:.4f}", label="Adjusted Slope", caption="Shrunk annual rate"),
            mo.stat(value=f"{_qual:.3f}", label="Quality Score", caption="Observational fidelity Q"),
        ],
        justify="space-between",
    )

    mo.vstack([
        mo.md("### 🔍 Country-Specific Trajectory Drilldown"),
        country_dropdown,
        mo.ui.altair_chart(c_chart),
        country_metrics,
    ])
    return


